typedef unsigned int u_int;
typedef unsigned long long big_int;

class string_buf
{
public:
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;

    inline bool is_equal(const string_buf &buf) const
    {
        if (buf.block_length != block_length) return false;
        for (int i = 0; i < block_length; i++) {
            if (!(buf.data[i] == data[i])) return false;
        }
        return true;
    }
};

class stringx
{
    friend inline bool operator==(const stringx& lhs, const stringx& rhs);
    char *chars;
    string_buf *my_buf;
public:
    stringx &operator=(const stringx &cp);
};

inline bool operator==(const stringx& lhs, const stringx& rhs)
{
    return lhs.my_buf->is_equal(*rhs.my_buf);
}

#define WAVE_TYPEMAX 3
#define wavewarn(a)

struct WaveScheduleTypeStruct {
    stringx name;
    float scale;
    float height;
};

extern WaveScheduleTypeStruct WAVE_ScheduleType[WAVE_TYPEMAX];
extern u_int WAVE_ScheduleTypeMax;
__asm__(".equ WAVE_ScheduleType, 0x0057B990");
__asm__(".equ WAVE_ScheduleTypeMax, 0x004846CC");

static u_int WAVE_CheckScheduleType(const stringx &typestr, float scale)
{
    u_int type = WAVE_TYPEMAX;

    for (u_int i = 0; i < WAVE_ScheduleTypeMax; ++i)
    {
        if (typestr == WAVE_ScheduleType[i].name && scale == WAVE_ScheduleType[i].scale)
        {
            type = i;
            break;
        }
    }
    if (type == WAVE_TYPEMAX)
    {
        if (WAVE_ScheduleTypeMax < WAVE_TYPEMAX)
        {
            type = WAVE_ScheduleTypeMax;
            WAVE_ScheduleType[WAVE_ScheduleTypeMax].name = typestr;
            WAVE_ScheduleType[WAVE_ScheduleTypeMax].scale = scale;
            ++WAVE_ScheduleTypeMax;
        }
        else
        {
            type = 0;
            wavewarn(("WAVE:\tToo many wave types in .beach file."));
            wavewarn(("WAVE:\tAt most %d variations of wave + scale are allowed.", WAVE_TYPEMAX));
            wavewarn(("WAVE:\tReplacing wave %s at scale %2.2f by wave %s at scale %2.2f.",
                typestr.c_str(), scale, WAVE_ScheduleType[0].name.c_str(), WAVE_ScheduleType[0].scale));
        }
    }

    return type;
}
